CloudFront & CDN:
# Create CloudFront distribution
aws cloudfront create-distribution \
  --origin-domain-name my-bucket.s3.us-east-1.amazonaws.com \
  --default-root-object index.html \
  --default-cache-behavior '{
    "TargetOriginId": "my-bucket",
    "ViewerProtocolPolicy": "redirect-to-https",
    "CachePolicyId": "658327ea-f89d-4fab-a63d-7e88639e58f6"
  }' \
  --enabled

# Origin Access Control (OAC)
aws cloudfront create-origin-access-control \
  --origin-access-control-config '{
    "Name": "my-oac",
    "SigningProtocol": "sigv4",
    "SigningBehavior": "always",
    "OriginAccessControlOriginType": "s3"
  }'

# Invalidate cache
aws cloudfront create-invalidation --distribution-id E1A2B3C4D5E6 --paths "/*" "/index.html"

# Lambda@Edge (Node.js — rewrite URI for SPA)
exports.handler = (event, context, callback) => {
  const request = event.Records[0].cf.request;
  if (request.uri !== "/" && !request.uri.includes(".")) {
    request.uri = "/index.html";
  }
  callback(null, request);
};

Step Functions & Workflows:
{
  "Comment": "Order processing with error handling",
  "StartAt": "ValidateOrder",
  "States": {
    "ValidateOrder": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:xxx:function:validate-order",
      "TimeoutSeconds": 30,
      "HeartbeatSeconds": 10,
      "Next": "ProcessPayment",
      "Retry": [{
        "ErrorEquals": ["Lambda.ServiceException", "Lambda.AWSLambdaException"],
        "IntervalSeconds": 2,
        "BackoffRate": 2,
        "MaxAttempts": 3
      }],
      "Catch": [{
        "ErrorEquals": ["States.ALL"],
        "Next": "NotifyFailure"
      }]
    },
    "ProcessPayment": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:xxx:function:process-payment",
      "Next": "ShipOrder"
    },
    "ShipOrder": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:xxx:function:ship-order",
      "End": true
    },
    "NotifyFailure": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:xxx:function:notify-failure",
      "End": true
    }
  }
}

